-- BhuView production-shaped PostgreSQL + PostGIS schema. All personal data is synthetic in demo seed.
CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY, name text NOT NULL, type text, state text, district text, status text DEFAULT 'active');
CREATE TABLE IF NOT EXISTS roles (id uuid PRIMARY KEY, name text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (id uuid PRIMARY KEY, code text UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, name text, email text UNIQUE NOT NULL, password_hash text NOT NULL, department_id uuid REFERENCES departments(id), status text DEFAULT 'active', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS user_roles (user_id uuid REFERENCES users(id), role_id uuid REFERENCES roles(id), PRIMARY KEY(user_id, role_id));
CREATE TABLE IF NOT EXISTS parcels (id uuid PRIMARY KEY, ulpin text UNIQUE NOT NULL, parcel_id text UNIQUE NOT NULL, survey_number text, state text, district text, taluk text, village text, area numeric, area_unit text, land_type text, geometry geometry(Polygon, 4326), centroid geometry(Point, 4326), status text DEFAULT 'active', created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS parcels_geometry_idx ON parcels USING GIST (geometry);
CREATE TABLE IF NOT EXISTS parcel_versions (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), version_no int, geometry geometry(Polygon,4326), land_use text, zoning text, changed_by uuid REFERENCES users(id), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS owners (id uuid PRIMARY KEY, name text, masked_identifier text, contact text);
CREATE TABLE IF NOT EXISTS parcel_owners (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), owner_id uuid REFERENCES owners(id), ownership_type text, ownership_percentage numeric, valid_from date, valid_to date);
CREATE TABLE IF NOT EXISTS ror_records (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), record_number text, owner_name text, area numeric, land_type text, source text, verified boolean DEFAULT false, last_updated timestamptz);
CREATE TABLE IF NOT EXISTS registrations (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), registration_number text, transaction_type text, transaction_date date, status text);
CREATE TABLE IF NOT EXISTS encumbrances (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), type text, holder text, status text, amount numeric);
CREATE TABLE IF NOT EXISTS land_use (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), category text, source text, effective_date date);
CREATE TABLE IF NOT EXISTS zoning (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), zone_code text, restrictions jsonb);
CREATE TABLE IF NOT EXISTS building_permissions (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), application_no text, status text, permitted_area numeric);
CREATE TABLE IF NOT EXISTS property_tax (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), fiscal_year text, status text, amount numeric);
CREATE TABLE IF NOT EXISTS utilities (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), utility_type text, geometry geometry(LineString,4326));
CREATE INDEX IF NOT EXISTS utilities_geometry_idx ON utilities USING GIST (geometry);
CREATE TABLE IF NOT EXISTS environmental_zones (id uuid PRIMARY KEY, name text, zone_type text, geometry geometry(Polygon,4326));
CREATE INDEX IF NOT EXISTS environmental_geometry_idx ON environmental_zones USING GIST (geometry);
CREATE TABLE IF NOT EXISTS disputes (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), case_no text, status text, description text);
CREATE TABLE IF NOT EXISTS service_requests (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), requested_by uuid REFERENCES users(id), request_type text, status text, remarks text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_instances (id uuid PRIMARY KEY, service_request_id uuid REFERENCES service_requests(id), current_status text, assigned_role text, updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS workflow_history (id bigserial PRIMARY KEY, workflow_id uuid REFERENCES workflow_instances(id), from_status text, to_status text, actor uuid REFERENCES users(id), remarks text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS documents (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), uploaded_by uuid REFERENCES users(id), document_type text, storage_key text, mime_type text, size_bytes bigint, status text, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS document_extractions (id uuid PRIMARY KEY, document_id uuid REFERENCES documents(id), extracted_fields jsonb, confidence numeric, mismatches jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS ai_alerts (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), alert_type text, severity text, confidence numeric, reasons jsonb, recommended_action text, status text);
CREATE TABLE IF NOT EXISTS risk_scores (id uuid PRIMARY KEY, parcel_id uuid REFERENCES parcels(id), score numeric, factors jsonb, calculated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_layers (id uuid PRIMARY KEY, name text, layer_type text, source text, geometry_type text, enabled boolean DEFAULT true);
CREATE TABLE IF NOT EXISTS gis_imports (id uuid PRIMARY KEY, layer_id uuid REFERENCES gis_layers(id), filename text, status text, validation_report jsonb, imported_by uuid REFERENCES users(id), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY, recipient uuid REFERENCES users(id), title text, message text, state text DEFAULT 'UNREAD', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id), role text, action text, module text, record_id text, status text, previous_value jsonb, new_value jsonb, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS government_data_sources (id uuid PRIMARY KEY, name text, provider_type text, endpoint text, is_official boolean DEFAULT false, status text, last_sync timestamptz, error_log text);
CREATE TABLE IF NOT EXISTS api_sync_jobs (id uuid PRIMARY KEY, source_id uuid REFERENCES government_data_sources(id), status text, started_at timestamptz, finished_at timestamptz, records_count int, error_log text);
